/// One of: f64 | str
#[derive(Debug, Clone)]
pub enum NumOrStr {
    Num(f64),
    Str(String),
}
impl<'de> Deserialize<'de> for NumOrStr {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let v = serde_json::Value::deserialize(d)?;
        if let Some(x) = jsnum::value_f64(&v) { return Ok(NumOrStr::Num(x)); }
        if let serde_json::Value::String(s) = &v { return Ok(NumOrStr::Str(s.clone())); }
        Err(serde::de::Error::custom("NumOrStr: unexpected value"))
    }
}
impl Digest for NumOrStr {
    fn digest(&self, h: &mut Fnv) {
        match self {
            NumOrStr::Num(x) => { h.f64(*x); }
            NumOrStr::Str(x) => { h.str(x); }
        }
    }
}

